#!/usr/bin/env bash
# Generates the agent instruction files from .agents/instructions/.
#
#   .agents/build-instructions.sh           write the generated files
#   .agents/build-instructions.sh --check   exit 1 if a generated file is out of date
#
# Sources, in file-name order:
#   .agents/instructions/[0-9]*.md          shared by all agents
#   .agents/instructions/claude/[0-9]*.md   only for Claude Code (optional)
#   .agents/instructions/codex/[0-9]*.md    only for Codex and other AGENTS.md readers (optional)
#
# Generated files:
#   AGENTS.md                    concatenation; AGENTS.md has no import syntax
#   CLAUDE.md                    @imports of the source files; Claude Code expands them at startup
#   .aiassistant/rules/bisq.md   same content as AGENTS.md, for JetBrains AI Assistant
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC=".agents/instructions"
MARKER="<!-- Generated by .agents/build-instructions.sh from .agents/instructions/. Do not edit this file. -->"

cd "$ROOT"
shopt -s nullglob

# Prints the source files for one agent, sorted by file name across the shared and agent directories.
sources() {
    local agent="$1"
    for f in "$SRC"/[0-9]*.md "$SRC/$agent"/[0-9]*.md; do
        printf '%s\t%s\n' "$(basename "$f")" "$f"
    done | sort | cut -f2
}

concatenate() {
    local first=true
    echo "$MARKER"
    echo
    while read -r f; do
        if [[ "$first" == false ]]; then
            printf '\n---\n\n'
        fi
        first=false
        cat "$f"
    done < <(sources codex)
}

generate() {
    local out="$1"
    mkdir -p "$out/.aiassistant/rules"
    concatenate > "$out/AGENTS.md"
    {
        echo "$MARKER"
        echo
        while read -r f; do
            echo "@$f"
        done < <(sources claude)
    } > "$out/CLAUDE.md"
    {
        printf -- '---\napply: always\n---\n\n'
        concatenate
    } > "$out/.aiassistant/rules/bisq.md"
}

GENERATED=(AGENTS.md CLAUDE.md .aiassistant/rules/bisq.md)

if [[ "${1:-}" == "--check" ]]; then
    tmp="$(mktemp -d)"
    trap 'rm -rf "$tmp"' EXIT
    generate "$tmp"
    status=0
    for f in "${GENERATED[@]}"; do
        if ! cmp -s "$tmp/$f" "$f"; then
            echo "$f is out of date. Run .agents/build-instructions.sh" >&2
            status=1
        fi
    done
    exit "$status"
fi

generate "$ROOT"
# Must not exceed project_doc_max_bytes in .codex/config.toml, or Codex drops the end of AGENTS.md.
if (( $(wc -c < AGENTS.md) > 65536 )); then
    echo "AGENTS.md exceeds 65536 bytes. Shorten the instructions or raise project_doc_max_bytes in .codex/config.toml" >&2
    exit 1
fi
for f in "${GENERATED[@]}"; do
    echo "$f: $(wc -l < "$f") lines, $(wc -c < "$f") bytes"
done
